1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
5	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
6	
7	/**
8	 * Normalizes the create-owner telephone by removing every non-digit character, then
9	 * requires exactly 10 digits. Runs after {@link RequireOwnerFields} (so the field is
10	 * present) and before {@link BuildOwner}, mutating the published body in place so the
11	 * mapped {@link org.springframework.samples.petclinic.model.Owner} — and the response —
12	 * carries the stripped 10-digit value. A telephone that is not exactly 10 digits after
13	 * stripping is rejected 400 via {@link InvalidTelephoneException}.
14	 */
15	public class NormalizeOwnerTelephone {
16	
17	    public void service(@Val OwnerFieldsDto request) throws InvalidTelephoneException {
18	        String digits = request.getTelephone().replaceAll("\\D", "");
19	        if (digits.length() != 10) {
20	            throw new InvalidTelephoneException(
21	                    "Telephone must be exactly 10 digits after removing non-digit characters");
22	        }
23	        request.setTelephone(digits);
24	    }
25	}
