3	import java.util.List;
4	
5	/**
6	 * Thrown when a create-owner request is missing or blank in one or more required
7	 * fields (firstName, lastName, address, city, telephone). Handled by
8	 * {@link MissingOwnerFieldsHandler}, which responds 400 with a JSON body whose
9	 * {@code errors} array lists the offending field names.
10	 */
11	public class MissingOwnerFieldsException extends Exception {
12	
13	    private final List<String> fields;
14	
15	    public MissingOwnerFieldsException(List<String> fields) {
16	        super("Missing or blank required fields: " + fields);
17	        this.fields = List.copyOf(fields);
18	    }
19	
20	    public List<String> getFields() {
21	        return this.fields;
22	    }
23	}
