9	import org.springframework.http.ResponseEntity;
10	
11	/**
12	 * Responds 400 to a {@link MissingOwnerFieldsException} with a JSON body whose
13	 * {@code errors} array lists the name of each missing or blank required field.
14	 */
15	public class MissingOwnerFieldsHandler {
16	
17	    public void handle(@Parameter MissingOwnerFieldsException ex,
18	            ObjectResponse<ResponseEntity<Map<String, List<String>>>> response) {
19	        response.send(ResponseEntity.status(HttpStatus.BAD_REQUEST)
20	                .body(Map.of("errors", ex.getFields())));
21	    }
22	}
